using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1: EF Core 9 renames the discriminator from
            // "Discriminator" to "$type". Existing documents and raw SQL
            // queries reference "Discriminator", so we pin the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2: EF Core 9 changed the id JSON property
            // from "EntityType|Key" (e.g. "Product|123") to just the raw
            // key value. We preserve the old format with a value converter
            // so existing 500K documents stay readable.
            entity.Property<string>("__id")
                  .ToJsonProperty("id")
                  .HasConversion(
                      v => v,
                      v => v)
                  .HasValueGenerator<LegacyProductIdGenerator>();

            // BREAKING CHANGE 3: HasIndex() on Cosmos now throws at model
            // build time instead of being silently ignored. Removed.
        });
    }
}

/// <summary>
/// Generates id values in the legacy EF Core 8 format: "Product|{key}".
/// </summary>
class LegacyProductIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
    {
        var key = entry.Property("Id").CurrentValue;
        return $"Product|{key}";
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

